"""Run an automatically generated EvoAgentX workflow and capture its real graph."""

from __future__ import annotations

import os
from typing import Any

from langsmith import traceable


def _plain(value: Any) -> Any:
    """Convert EvoAgentX objects into JSON-friendly Python values."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(k): _plain(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_plain(v) for v in value]
    if hasattr(value, "model_dump"):
        try:
            return _plain(value.model_dump(mode="json", exclude_none=True))
        except TypeError:
            return _plain(value.model_dump(exclude_none=True))
        except Exception:
            pass
    if hasattr(value, "to_dict"):
        try:
            return _plain(value.to_dict())
        except Exception:
            pass
    return str(value)


def serialize_generated_graph(graph) -> dict:
    """Capture the actual graph generated by EvoAgentX."""
    nodes = []
    for node in getattr(graph, "nodes", []) or []:
        node_data = _plain(node.to_dict()) if hasattr(node, "to_dict") else _plain(node)
        if not isinstance(node_data, dict):
            node_data = {"value": node_data}
        try:
            node_data["agents"] = _plain(node.get_agents())
        except Exception:
            node_data["agents"] = []
        nodes.append(node_data)

    edges = []
    for edge in getattr(graph, "edges", []) or []:
        edges.append(
            _plain(edge.model_dump(exclude_none=True))
            if hasattr(edge, "model_dump")
            else _plain(edge)
        )

    workflow_inputs = getattr(graph, "workflow_inputs", None) or []
    workflow_outputs = getattr(graph, "workflow_outputs", None) or []

    return {
        "goal": str(getattr(graph, "goal", "")),
        "nodes": nodes,
        "edges": edges,
        "workflow_inputs": [_plain(x) for x in workflow_inputs],
        "workflow_outputs": [_plain(x) for x in workflow_outputs],
        "node_count": len(nodes),
        "edge_count": len(edges),
        "graph_source": "EvoAgentX WorkFlowGenerator.generate_workflow",
    }


def _make_inputs(graph, goal: str, supplied_inputs: dict | None = None) -> dict:
    supplied = dict(supplied_inputs or {})
    declared = list(getattr(graph, "workflow_inputs", None) or [])
    names = []
    for item in declared:
        name = getattr(item, "name", None)
        if name is None and isinstance(item, dict):
            name = item.get("name")
        if name:
            names.append(name)

    if "goal" in names and "goal" not in supplied:
        supplied["goal"] = goal

    required = []
    for item in declared:
        data = _plain(item)
        if isinstance(data, dict) and data.get("required", False):
            name = data.get("name")
            if name and name not in supplied:
                required.append(name)

    if len(required) == 1:
        supplied[required[0]] = goal
        required = []

    if required:
        raise ValueError(
            "EvoAgentX generated required workflow inputs that were not provided: "
            + ", ".join(required)
        )
    return supplied


@traceable(name="EvoAgentX workflow generation", run_type="chain")
def _generate_workflow(generator, goal: str):
    return generator.generate_workflow(goal=goal)


@traceable(name="EvoAgentX generated workflow execution", run_type="chain")
def _execute_workflow(workflow, inputs: dict):
    return workflow.execute(inputs=inputs)


@traceable(name="EvoAgentX Phase 1 - Auto-generated workflow", run_type="chain")
def run_evoagentx(
    goal: str,
    model_name: str,
    run_label: str = "phase1-run",
    evolution_type: str = "Workflow",
    workflow_version: str = "generated",
    workflow_inputs: dict | None = None,
):
    """Generate, capture, and execute a real EvoAgentX-generated workflow."""
    from evoagentx.models import LiteLLMConfig, LiteLLM
    from evoagentx.workflow import WorkFlow, WorkFlowGenerator
    from evoagentx.agents import AgentManager

    api_key = os.getenv("GEMINI_API_KEY", "").strip()
    if not api_key:
        raise RuntimeError(
            "GEMINI_API_KEY is missing. Enter your Gemini API key in the Streamlit sidebar."
        )
    if not goal or len(goal.strip()) < 10:
        raise ValueError("Please enter a descriptive goal of at least 10 characters.")
    if not model_name or not model_name.strip():
        raise ValueError("Please enter a Gemini model name.")

    config = LiteLLMConfig(
        model=model_name.strip(),
        gemini_key=api_key,
        max_tokens=2048,
        stream=False,
        output_response=False,
    )
    llm = LiteLLM(config=config)

    # EvoAgentX generates the workflow automatically from the supplied goal.
    generator = WorkFlowGenerator(llm=llm)
    graph = _generate_workflow(generator, goal.strip())

    # Capture the real graph before execution can reset node state.
    graph_data = serialize_generated_graph(graph)
    inputs = _make_inputs(graph, goal.strip(), workflow_inputs)

    manager = AgentManager()
    manager.add_agents_from_workflow(graph, llm_config=config)

    workflow = WorkFlow(
        graph=graph,
        agent_manager=manager,
        llm=llm,
    )
    result = _execute_workflow(workflow, inputs)

    status_value = getattr(result, "status", "unknown")
    status = str(getattr(status_value, "value", status_value))
    if status.lower() not in {"success", "succeeded", "completed"}:
        message = (
            getattr(result, "displayable_error", None)
            or getattr(result, "error_msg", None)
            or "Unknown workflow execution error"
        )
        raise RuntimeError(f"EvoAgentX workflow status={status}: {message}")

    output = getattr(result, "result", result)
    return {
        "run_label": run_label,
        "evolution_type": evolution_type,
        "workflow_version": workflow_version,
        "workflow_status": status,
        "goal": goal.strip(),
        "model_name": model_name.strip(),
        "workflow_inputs_used": _plain(inputs),
        "generated_graph": graph_data,
        "output": str(output)[:12000],
    }
